           return CheckpointPolicy.PREFER_RECOMPUTE\\n            return CheckpointPolicy.MUST_SAVE\\n\\n        return create_selective_checkpoint_contexts(_policy)\\n\\n    _orig = _cp.checkpoint\\n\\n    @functools.wraps(_orig)\\n    def _sac_checkpoint(function, *args, use_reentrant=None, context_fn=_cp.noop_context_fn, **kwargs):\\n        if context_fn is _cp.noop_context_fn:\\n            context_fn = _context_fn\\n        return _orig(function, *args, use_reentrant=False, context_fn=context_fn, **kwargs)\\n\\n    _cp.checkpoint = _sac_checkpoint\\n    for _mod in list(sys.modules.values()):\\n        _d = getattr(_mod, '__dict__', None)\\n        if not isinstance(_d, dict):\\n            continue\\n        for _attr in ('checkpoint', 'torch_utils_checkpoint'):\\n            if _d.get(_attr) is _orig:\\n                _d[_attr] = _sac_checkpoint\\n    print(f'[train_patches:{_TAG}] selective checkpoint installed (every_other_mm={SAVE_EVERY_OTHER_MM})', flush=True)\\nexcept Exception as e:\\n    print(f'[train_patches:{_TAG}] not installed: {e}', flush=True)\\n\"}],\"predicted_gain_pct\":7.0,\"uncertainty_pct\":8.0,\"p_feasible\":0.5,\"change_class\":\"execution\",\"rationale\":\"every_n_layers 2/3 ran 0.25% slower while every_n_layers 4 OOMed. That pattern fits every_n_layers grouping layers into larger checkpoint segments: more peak memory, same full recompute. So full recompute is still paid, and rule H7 puts it at about 21% vs about 4% for selective. Saving half of the GEMM outputs plus the attention outputs removes roughly half of the recompute GEMM FLOPs and all of the attention recompute. Estimated extra memory at mbs 2 is about 15-18 GiB, which fits the accounting margin of 67 GiB but is uncertain given c2's peak. The arithmetic is identical, so the loss should not move.\",\"memory\":{\"direction\":\"spends\",\"gib\":17.0},\"warmup_updates\":2},{\"mechanism\":"}], "container": null, "stop_reason": null, "stop_sequence": null, "stop_details": null, "u