ption as _e:\\n        _fla_err = repr(_e)\\n\\n\\ndef _make_dispatch(orig):\\n    sig = inspect.signature(orig, follow_wrapped=False)\\n    names = [n for n in sig.parameters if n not in ('self', 'cls')]\\n    if len(names) < 2 or 'activation' not in sig.parameters or 'bias' not in sig.parameters:\\n        return None\\n    x_name = names[0]\\n    w_name = 'weight' if 'weight' in sig.parameters else names[1]\\n    known = {x_name, w_name, 'bias', 'activation', 'self', 'cls'}\\n\\n    def dispatch(*args, **kwargs):\\n        ok = False\\n        if not _STATE['broken']:\\n            try:\\n                ba = sig.bind(*args, **kwargs)\\n                ba.apply_defaults()\\n                a = ba.arguments\\n                x, w, b, act = a[x_name], a[w_name], a['bias'], a['activation']\\n                ok = (isinstance(x, torch.Tensor) and isinstance(w, torch.Tensor) and x.is_cuda and x.dim() == 3\\n                      and act in (None, 'silu', 'swish')\\n                      and (b is None or (isinstance(b, torch.Tensor) and b.dim() == 1)))\\n                for p in sig.parameters.values():\\n                    if not ok:\\n                        break\\n                    if p.name in known:\\n                        continue\\n                    v = a.get(p.name)\\n                    if p.kind in (p.VAR_POSITIONAL, p.VAR_KEYWORD):\\n                        ok = not v\\n                    else:\\n                        ok = v is None or v is False\\n                if ok and w.dim() == 3 and w.shape[1] == 1:\\n                    w = w.squeeze(1)\\n                ok = ok and w.dim() == 2 and x.shape[1] == w.shape[0] and (b is None or b.shape[0] == w.shape[0])\\n            except Exception:\\n                ok = False\\n        if not ok:\\n            return orig(*args, **kwargs)\\n        try:\\n            y = _fla_conv(x.transpose(1, 2).contiguous(), weight=w, bias=b, activation=act)\\n        except Exception as e:\\n            _STATE['brok